predicted_python:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics.org"
DATABASE = "metadata_index"
COLLECTION = "data_assets"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find 5 subjects that appear in assets with 3+ different modalities
agg_pipeline = [
    # Match documents that have subject_id and modality fields
    {
        "$match": {
            "subject.subject_id": {"$exists": True, "$ne": None},
            "data_description.modality": {"$exists": True, "$ne": None}
        }
    },
    # Unwind the modality array to work with individual modalities
    {
        "$unwind": "$data_description.modality"
    },
    # Group by subject_id and modality to get unique combinations
    {
        "$group": {
            "_id": {
                "subject_id": "$subject.subject_id",
                "modality": "$data_description.modality.name"
            }
        }
    },
    # Group by subject_id to count distinct modalities and collect them
    {
        "$group": {
            "_id": "$_id.subject_id",
            "modalityCount": {"$sum": 1},
            "modalities": {"$push": "$_id.modality"}
        }
    },
    # Filter for subjects with at least 3 different modalities
    {
        "$match": {
            "modalityCount": {"$gte": 3}
        }
    },
    # Sort by number of modalities (descending)
    {
        "$sort": {
            "modalityCount": -1
        }
    },
    # Limit to 5 results
    {
        "$limit": 5
    },
    # Format the output
    {
        "$project": {
            "subject_id": "$_id",
            "modalityCount": 1,
            "modalities": 1,
            "_id": 0
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

