import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics.org"
DATABASE = "metadata_index"
COLLECTION = "data_assets"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find mice in "Thalamus in the middle" project with VM injections
# and extract their subject IDs and virus names
agg_pipeline = [
    # Match documents for the specific project and with VM as targeted structure
    {
        "$match": {
            "data_description.project_name": "Thalamus in the middle",
            "procedures.subject_procedures": {
                "$elemMatch": {
                    "procedures": {
                        "$elemMatch": {
                            "targeted_structure": "VM"
                        }
                    }
                }
            }
        }
    },
    # Unwind the subject procedures to access individual procedures
    {
        "$unwind": "$procedures.subject_procedures"
    },
    # Unwind the procedures to access individual procedure details
    {
        "$unwind": "$procedures.subject_procedures.procedures"
    },
    # Filter to keep only VM injections
    {
        "$match": {
            "procedures.subject_procedures.procedures.targeted_structure": "VM"
        }
    },
    # Project only the fields we need
    {
        "$project": {
            "_id": 0,
            "subject_id": "$procedures.subject_id",
            "virus_name": "$procedures.subject_procedures.procedures.virus_name"
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

