from aind_data_access_api.document_db import MetadataDbClient

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)
agg_pipeline = [
    {
        "$match": {
            "data_description.modality": {"$exists": True}
        }
    },
    {
        "$project": {
            "subject_id": "$data_description.subject_id", 
            "modalities": "$data_description.modality.name"
        }
    },
    {
        "$match": {
            "subject_id": {"$exists": True, "$ne": None}
        }
    },
    {
        "$unwind": "$modalities"
    },
    {
        "$group": {
            "_id": "$subject_id", 
            "modalities": {"$addToSet": "$modalities"}
        }
    },
    {
        "$match": {
            "$and": [
                {"modalities": {"$regex": "optical physiology", "$options": "i"}},
                {"modalities": {"$regex": "behavior", "$options": "i"}}
            ]
        }
    },
    {
        "$project": {
            "_id": 0, 
            "subject_id": "$_id", 
            "modalities": 1
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)


# Optional: Count of subjects
print(f"Total Subjects Found: {len(result)}")

predicted_python:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics.org"
DATABASE = "metadata_index"
COLLECTION = "data_assets"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to count subjects with both optical physiology and behavior data streams
agg_pipeline = [
    # Match documents that have session data
    {"$match": {"session": {"$exists": True, "$ne": None}}},

    # Project only the fields we need
    {"$project": {
        "subject_id": "$subject.subject_id",
        "data_streams": "$session.data_streams"
    }},

    # Unwind the data_streams array to work with individual streams
    {"$unwind": "$data_streams"},

    # Group by subject_id and collect unique modalities
    {"$group": {
        "_id": "$subject_id",
        "modalities": {"$addToSet": "$data_streams.modality"}
    }},

    # Filter for subjects that have both modalities
    {"$match": {
        "modalities": {"$all": ["Optical physiology", "Behavior"]}
    }},

    # Count the results
    {"$count": "subjects_with_both_modalities"}
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

