)

# Aggregation pipeline to calculate percentage of fiber photometry experiments with behavioral data
agg_pipeline = [
    # Match documents that are fiber photometry experiments
    {"$match": {"data_description.modality.name": "Fiber photometry"}},

    # Project fields and create a has_behavior field that checks if any behavior modality exists
    {"$project": {
        "_id": 1,
        "name": 1,
        "has_behavior": {
            "$cond": {
                "if": {
                    "$or": [
