                        {"$in": ["Behavior videos", "$data_description.modality.name"]},
                        {"$in": ["Trained behavior", "$data_description.modality.name"]}
                    ]
                },
                "then": True,
                "else": False
            }
        }
    }},

    # Group all documents to calculate totals
    {"$group": {
        "_id": None,
        "total": {"$sum": 1},
        "with_behavior": {"$sum": {"$cond": ["$has_behavior", 1, 0]}}
